const scenario=String($input.first().json.body?.scenario??"").trim();
const samples={
 happy:{runKey:"cap-happy",leadId:"L-1201",fullName:"Mina Yilmaz",email:"mina@example.com",source:"website",budget:6500,targetUrl:"https://api.example.com/crm",manualMinutes:14,monthlyVolume:320,hourlyRate:42,platformCost:180,projectCost:4800,expectedRoute:"sales_standard"},
 high:{runKey:"cap-high",leadId:"L-1202",fullName:"Jörg Müller",email:"joerg@example.com",source:"partner",budget:18000,targetUrl:"https://api.example.com/crm",manualMinutes:18,monthlyVolume:450,hourlyRate:48,platformCost:240,projectCost:6500,expectedRoute:"sales_priority"},
 invalid:{runKey:"cap-invalid",leadId:"",fullName:"Broken Lead",email:"not-an-email",source:"website",budget:9000,targetUrl:"https://api.example.com/crm",manualMinutes:14,monthlyVolume:320,hourlyRate:42,platformCost:180,projectCost:4800,expectedRoute:"validation_reject"},
 security:{runKey:"cap-security",leadId:"L-1204",fullName:"Security Test",email:"security@example.com",source:"upload",budget:12000,targetUrl:"http://169.254.169.254/latest/meta-data/",manualMinutes:16,monthlyVolume:300,hourlyRate:45,platformCost:200,projectCost:6000,expectedRoute:"security_review"},
 weakroi:{runKey:"cap-weakroi",leadId:"L-1205",fullName:"Small Volume",email:"small@example.com",source:"website",budget:4000,targetUrl:"https://api.example.com/crm",manualMinutes:5,monthlyVolume:20,hourlyRate:35,platformCost:300,projectCost:9000,expectedRoute:"sales_standard"}
};
const s=samples[scenario];
if(!s)return [{json:{validScenario:false,scenario,error:"unknown_scenario"}}];
return [{json:{validScenario:true,scenario,...s}}];

const child=$input.first().json;
const p=$('Prepare Project Scenario').item.json;
const rawTarget=String(p.targetUrl||"").trim();
const m=rawTarget.match(/^([a-z][a-z0-9+.-]*):\/\/([^\/?#]+)/i);
let securityAllowed=true,securityReason="allowed";
if(!m){securityAllowed=false;securityReason="invalid_target_url";}
else{
 const proto=String(m[1]||"").toLowerCase();
 let host=String(m[2]||"").replace(/^[^@]+@/,"").replace(/:\d+$/,"").toLowerCase();
 if(host.startsWith("[")&&host.endsWith("]"))host=host.slice(1,-1);
 const blocked=[/^localhost$/, /^127\./, /^10\./, /^192\.168\./, /^169\.254\./, /^172\.(1[6-9]|2\d|3[0-1])\./, /^0\./, /^::1$/, /^fc[0-9a-f]{2}:/i, /^fd[0-9a-f]{2}:/i, /^fe[89ab][0-9a-f]:/i];
 if(proto!=="https"){securityAllowed=false;securityReason="non_https_target";}
 if(blocked.some(rx=>rx.test(host))){securityAllowed=false;securityReason="private_or_link_local_target";}
}

let route;
if(!child.valid)route="validation_reject";
else if(!securityAllowed)route="security_review";
else if(Number(p.budget)>=10000)route="sales_priority";
else route="sales_standard";

const manualMonthlyHours=(Number(p.manualMinutes)*Number(p.monthlyVolume))/60;
const manualMonthlyCost=manualMonthlyHours*Number(p.hourlyRate);
const residualMinutes=2;
const automationLabor=((residualMinutes*Number(p.monthlyVolume))/60)*Number(p.hourlyRate);
const monthlyAutomationCost=automationLabor+Number(p.platformCost);
const monthlySavings=manualMonthlyCost-monthlyAutomationCost;
const paybackMonths=monthlySavings>0?Number(p.projectCost)/monthlySavings:null;
const routeMatches=route===p.expectedRoute;

const acceptance={
 contractValid: p.scenario==="invalid" ? child.valid===false : child.valid===true,
 securityBehavior: p.scenario==="security" ? securityAllowed===false : securityAllowed===true,
 expectedRoute: routeMatches,
 noUnapprovedExternalSideEffect:true,
 evidencePersistable:true
};
const acceptancePassed=Object.values(acceptance).every(Boolean);
return [{json:{
 scenario:p.scenario,runKey:p.runKey,owner:"BAIS Academy Learner",
 input:{leadId:p.leadId,source:p.source,budget:p.budget,targetUrl:p.targetUrl},
 normalized:child,
 security:{allowed:securityAllowed,reason:securityReason},
 decision:{route,expectedRoute:p.expectedRoute,routeMatches},
 economics:{
  manualMinutesPerCase:p.manualMinutes,monthlyVolume:p.monthlyVolume,hourlyRate:p.hourlyRate,
  manualMonthlyHours:Number(manualMonthlyHours.toFixed(2)),
  manualMonthlyCost:Number(manualMonthlyCost.toFixed(2)),
  residualMinutesPerCase:residualMinutes,
  automationLaborCost:Number(automationLabor.toFixed(2)),
  platformCost:Number(p.platformCost),
  monthlyAutomationCost:Number(monthlyAutomationCost.toFixed(2)),
  monthlySavings:Number(monthlySavings.toFixed(2)),
  projectCost:Number(p.projectCost),
  paybackMonths:paybackMonths===null?null:Number(paybackMonths.toFixed(2)),
  positiveBusinessCase:monthlySavings>0
 },
 acceptance,
 acceptancePassed
}}];

const row=$input.first().json;
const x=$('Evaluate Architecture ROI Acceptance').item.json;
return [{json:{
 ok:true,module:"12",case:x.scenario,
 project:{
  phase:"acceptance_evidence",
  pattern:"discovery -> contract -> security gate -> routing -> economics -> acceptance -> persisted evidence",
  owner:x.owner
 },
 normalized:x.normalized,
 security:x.security,
 decision:x.decision,
 economics:x.economics,
 acceptance:x.acceptance,
 acceptancePassed:x.acceptancePassed,
 evidence:{
  persistence:"n8n_data_table",
  table:"BAIS Academy Modul 12 Project Evidence",
  rowId:row.id??null,
  runKey:x.runKey,
  route:row.route??x.decision.route,
  updatedAt:row.updatedAt??null
 },
 handover:{
  productionSideEffectsExecuted:false,
  requiredBeforeRealGoLive:["customer approval","production credentials","security review","monitoring/alerts","rollback plan","runbook","data-processing review"],
  status:x.acceptancePassed?"technical_acceptance_passed":"technical_acceptance_failed"
 },
 lesson:x.scenario==="weakroi"
  ?"A technically valid automation can still have a weak or negative business case; ROI is a separate acceptance dimension."
  :x.scenario==="security"
   ?"Security acceptance must block unsafe architecture even if the business data itself is valid."
   :x.scenario==="invalid"
    ?"Input contract and validation reject bad data before downstream systems."
    :"The capstone connects reusable components, security, routing, economics and persisted acceptance evidence."
}}];
